import {escapeHTML as e, safeURL, matches, readiness, normalizeCases, planText} from './evidence-logic.js';
const $ = selector => document.querySelector(selector);
const main = $('#content');
const storageKey = 'arc.field.v2';
let saved = {};
try { saved = JSON.parse(localStorage.getItem(storageKey) || '{}') || {}; } catch {}
const state = {inventory:saved.inventory && typeof saved.inventory==='object'?saved.inventory:{}, tests:saved.tests&&typeof saved.tests==='object'?saved.tests:{}, cases:normalizeCases(saved.cases), query:'', category:'all'};
let data, sources, assets, currentMode = 'routes', toastTimer;
const categoryNames = {all:'Вся техника',camera:'Камеры',washer:'Стиральные машины',dryer:'Сушилки'};
const captions = {
 'esp32-board-photo':'AI-Thinker ESP32-CAM с камерой. Фотография из документации Prusa.',
 'esp32-parts-photo':'Чипы на конкретном образце: ESP32-S, AMS1117 3.3 и IPS6404LSQ. У других плат состав может отличаться.',
 'esp32-variants':'Два варианта платы с маркировками GND/R и GND. Сверяй свой экземпляр перед выбором программатора.',
 'esp32-schematic':'Принципиальная схема ESP32_CAM v1.6, 30.01.2018. Копия из документации Prusa; ревизия документа не подтверждает ревизию твоей платы.',
 'esp32-pinout':'Расположение выводов AI-Thinker ESP32-CAM. Логические уровни UART — 3,3 V.',
 'rpi-csi-schematic':'Официальная схема 15-контактного разъёма CSI Raspberry Pi. Это разъём, а не полная схема Camera Module 2.',
 'washer-electrolux-ewf12844-0':'Разъёмы EWX14. Оригинальная фотография Matthew Chapman; PNC исходной машины не указан.',
 'washer-electrolux-ewf12844-1':'Питание сфотографированного EWX14. Обозначения автора разбора.',
 'dryer-aeg-t55640-bemmelen-0':'Шильдик: T55640 / P502664 / PNC 91609628602.',
 'dryer-aeg-t55640-bemmelen-1':'Контрольная плата из фоторемонта Albert van Bemmelen. Номер ревизии не установлен.',
 'dryer-aeg-t55640-bemmelen-2':'Обратная сторона платы из того же фоторемонта.',
 'dryer-aeg-t55640-bemmelen-3':'Контроллер питания LNK304. Суффикс по этому снимку надёжно не прочитан.'
};
function notify(message) { clearTimeout(toastTimer); $('#toast').textContent=message; $('#toast').classList.add('visible'); toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200); }
function save() { try { localStorage.setItem(storageKey,JSON.stringify({inventory:state.inventory,tests:state.tests,cases:state.cases})); return true; } catch { notify('Браузер не сохранил изменения. Можно экспортировать данные в файл.'); return false; } }
function download(name, body, type='text/plain;charset=utf-8') { const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([body],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000); }
function links(ids) { return `<div class="inline-sources">${ids.map(id=>{const s=sources.get(id);return s?`<a href="${safeURL(s.url)}" target="_blank" rel="noopener" title="${e(s.title)}">[${data.sources.indexOf(s)+1}] ${e(new URL(s.url).hostname.replace('www.',''))} ↗</a>`:'';}).join('')}</div>`; }
function sourceRows(ids=data.sources.map(s=>s.id)) { return ids.map(id=>{const s=sources.get(id);if(!s)return '';return `<div class="source-row"><a href="${safeURL(s.url)}" target="_blank" rel="noopener"><b class="source-number">${String(data.sources.indexOf(s)+1).padStart(2,'0')}</b>${e(s.title)} ↗</a><span>${e(s.author||'Документация проекта')} · ${e(new URL(s.url).hostname)}${s.published?' · '+e(s.published.slice(0,10)):''}</span></div>`;}).join(''); }
function figure(id,diagram=false) { const a=assets.get(id);if(!a)return '';return `<figure class="figure ${diagram?'diagram':''}"><button class="figure-button" data-image="${e(id)}" aria-label="Увеличить: ${e(captions[id]||a.caption||a.id)}"><img src="${e(a.src)}" alt="${e(captions[id]||a.caption||a.id)}" loading="lazy" referrerpolicy="no-referrer"></button><figcaption>${e(captions[id]||a.caption||a.id)}<br>${e(a.credit)} · <a href="${safeURL(a.url)}" target="_blank" rel="noopener">Оригинал ↗</a>${a.license?' · '+e(a.license):''}</figcaption></figure>`; }
function technicalGraphic(type) {
 const isWasher=type==='washer';
 return `<svg class="small-diagram" viewBox="0 0 360 190" fill="none" role="img" aria-label="${isWasher?'Карта плат машины, иллюстрация ARC':'Камера, USB-мост и компьютер, иллюстрация ARC'}"><g stroke="#829174" stroke-width="1.4">${isWasher?'<rect x="98" y="17" width="164" height="50" rx="4"/><rect x="16" y="124" width="143" height="50" rx="4"/><rect x="201" y="124" width="143" height="50" rx="4"/><path d="M180 67v25H87v32m93-32h92v32"/>':'<rect x="16" y="55" width="95" height="80" rx="7"/><circle cx="63" cy="95" r="24"/><circle cx="63" cy="95" r="11"/><rect x="145" y="65" width="75" height="60" rx="4"/><path d="M111 95h34m75 0h30"/><rect x="250" y="43" width="95" height="87" rx="4"/><path d="M297 130v17m-21 0h42"/>'}</g><g fill="#44583b" font-family="monospace" font-size="12" text-anchor="middle">${isWasher?'<text x="180" y="47">EWX14</text><text x="87" y="154">EMC14</text><text x="272" y="154">TC4-EUI14</text>':'<text x="63" y="163">OV772x</text><text x="182" y="99">OV534</text><text x="297" y="96">LINUX</text><text x="235" y="82" font-size="9">USB</text>'}</g></svg>`;
}
function cover(item,index) {
 const a=assets.get(item.image);const isPhoto=item.id==='ewx14-sample'||item.id==='aeg-t55640';
 return `<div class="card-cover ${isPhoto?'photo':''}"><span class="card-code">ARC / ${String(index+1).padStart(2,'0')}</span>${a?`<img src="${e(a.src)}" alt="${e(captions[item.image]||item.title)}" loading="lazy" referrerpolicy="no-referrer">`:technicalGraphic(item.category)}</div>`;
}
function card(item,index,kind) {
 const isRoute=kind==='routes';const href=isRoute?`#build/${item.id}`:`#device/${item.id}`;
 return `<article class="catalog-card"><a href="${href}" class="card-title">${cover(item,index)}<div class="card-body"><span class="tagline">${isRoute?'Маршрут по документации':e(categoryNames[item.category]||'Устройство')}</span><h3>${e(item.title)}</h3><p>${e(item.subtitle)}</p><div class="card-foot"><span>${isRoute?`${item.requirements.length} позиций · ${item.steps.length} шагов`:`${item.chips.length} компонентов / узлов · источники внутри`}</span><b class="arrow">↗</b></div></div></a></article>`;
}
function catalogPage(mode) {
 currentMode=mode;state.query='';state.category='all';
 const device=mode==='devices';
 main.innerHTML=`<div class="wrap"><section class="hero"><div><span class="eyebrow">Полевой справочник / 002</span><h1>${device?'Сначала узнай,<br>что внутри.':'Полезные вещи.<br>Из старой техники.'}</h1><p>${device?'Найди модель или маркировку платы. Посмотри реальные фотографии, компоненты и схемы — и пойми, что можно использовать дальше.':'Камера из старого модуля. Датчик из сломанного прибора. Найди детали, проверь совместимость и пройди путь до первого рабочего запуска.'}</p><div class="hero-actions"><button class="btn primary" data-jump="catalog">${device?'Найти устройство':'Выбрать сборку'} <span>↓</span></button><a class="btn" href="${device?'#explore':'#devices'}">${device?'Хочу собрать устройство':'У меня есть старая техника'} <span>↗</span></a></div></div><a class="hero-specimen" href="#device/esp32-cam"><div class="specimen-label"><span>ПОЛЕВЫЕ ЗАМЕТКИ / 01</span><span>WI-FI · 2.4 GHz</span></div><img src="assets/evidence/esp32-cam.jpg" alt="Фотография AI-Thinker ESP32-CAM из документации Prusa"><div class="specimen-foot"><div>Маленькая плата. Уже камера.<br><span>OV2640 → ESP32-S → Wi-Fi</span></div><b>↗</b></div><div class="specimen-credit">Фото: Prusa Research · открыть разбор</div></a></section><div class="path-strip"><span><b>01</b> Найти технику</span><i>→</i><span><b>02</b> Узнать плату и чипы</span><i>→</i><span><b>03</b> Собрать по схеме</span><i>→</i><span><b>04</b> Проверить результат</span></div><section id="catalog"><div class="section-heading"><div><h2>${device?'Техника под разбор':'С чего начать'}</h2><p>${device?'Конкретные модели и образцы плат. Каждый вывод связан с источником.':'Три маршрута от деталей до изображения. С составом, настройкой и проверкой.'}</p></div><a class="small-link" href="#learn">Как читать карточки ↗</a></div><div class="toolbar">${device?`<div class="filters">${Object.entries(categoryNames).map(([id,name])=>`<button class="pill" data-category="${id}" aria-pressed="${id==='all'}">${name}</button>`).join('')}</div>`:'<span class="tagline">Камеры / первый рабочий запуск</span>'}<label class="search"><span aria-hidden="true">⌕</span><input id="catalog-search" type="search" placeholder="${device?'Модель, плата или чип…':'Поиск сборки или компонента…'}" aria-label="Поиск ${device?'устройства':'сборки'}"></label></div><div id="catalog-grid" class="grid"></div><div class="catalog-note"><span class="dot"></span><span id="catalog-count"></span></div></section>${device?'':`<section class="other-goals"><div class="section-heading"><div><h2>Другие задачи</h2><p>Эскизы из первой версии ARC. Аппаратные испытания ещё не проведены.</p></div></div><div class="mini-grid"><a class="mini-card" href="archive.html#build=arc:alarm"><span class="number">СИГНАЛИЗАЦИЯ / ЭСКИЗ</span><h3>Датчик открытой двери ↗</h3><p>Arduino, геркон и зуммер. Комплект и учебный скетч.</p></a><a class="mini-card" href="archive.html#build=arc:wick"><span class="number">ПОЛИВ / ЭСКИЗ</span><h3>Полив без электроники ↗</h3><p>Ёмкость, фитиль и проверка подачи воды для конкретного растения.</p></a><a class="mini-card" href="archive.html#build=arc:watch"><span class="number">НАБЛЮДЕНИЕ / ЭСКИЗ</span><h3>Запись с USB-камеры ↗</h3><p>Локальный компьютер, совместимая камера и Motion.</p></a></div></section>`}<section class="field-banner"><div><span class="eyebrow">От форума до рабочего устройства</span><h2>Знать название чипа — только начало.</h2></div><div><p>Нужны модель и ревизия, питание, интерфейс, драйвер и проверка. ARC связывает это в один маршрут и показывает, где данных пока не хватает.</p><a href="#learn" class="btn">Как пройти весь путь <span>↗</span></a></div></section></div>`;
 renderCards();
}
function renderCards() {
 const list=data[currentMode].filter(r=>(state.category==='all'||r.category===state.category)&&matches(r,state.query));
 $('#catalog-grid').innerHTML=list.length?list.map((r,i)=>card(r,i,currentMode)).join(''):`<div class="empty"><h3>В проверенной подборке пока нет совпадений.</h3><p>Попробуй маркировку чипа, другое название или исходный корпус.</p><a class="btn" href="archive.html">Открыть исходный корпус ↗</a></div>`;
 $('#catalog-count').textContent=`Найдено: ${list.length}. ${currentMode==='routes'?'Маршруты сверены с документацией. На оборудовании ARC пока не испытаны.':'Наблюдения относятся к указанным моделям и образцам; ревизии не объединяются автоматически.'}`;
}
function section(id,n,title,content) { return `<section class="detail-section" id="${id}"><h2><span class="section-number">${n}</span>${title}</h2>${content}</section>`; }
function outline(items,extra='') { return `<aside class="outline"><span>В ЭТОМ РАЗБОРЕ</span>${items.map(([id,label])=>`<button data-jump="${id}">${label}</button>`).join('')}${extra}</aside>`; }
function bullets(items) { return `<ul class="clean-list">${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul>`; }
function devicePage(id) {
 const d=data.devices.find(d=>d.id===id);if(!d)return notFound();
 const items=[['identity','Что это за устройство'],['chips','Плата и компоненты'],['diagrams','Фото и схемы'],['reuse','Что можно использовать'],['evidence','Что подтверждено'],['sources','Источники']];
 let architecture='';if(d.id==='ewf12844')architecture=`<div class="arch"><div>Главная плата <small>EWX14</small></div><div>Инвертор двигателя <small>EMC14 CIM</small></div><div>Панель управления <small>TC4-EUI14P40</small></div><p>Карта узлов ARC по каталогу производителя. Электрическая схема — в PDF ниже.</p></div>`;
 const chips=`<div class="table-wrap"><table><thead><tr><th>Маркировка</th><th>Зачем нужна</th><th>Где подтверждено</th></tr></thead><tbody>${d.chips.map(c=>`<tr><td>${e(c.name)}</td><td>${e(c.role)}</td><td>${e(c.scope)}${links(c.source_ids)}</td></tr>`).join('')}</tbody></table></div><div class="callout"><strong>Что ещё неизвестно</strong>${bullets(d.unknown)}</div>`;
 const diagrams=`${d.gallery.length?`<div class="gallery">${d.gallery.map(id=>figure(id)).join('')}</div>`:''}${d.diagrams.map(id=>figure(id,true)).join('')}${(d.documents||[]).map(doc=>`<a class="document-link" href="${safeURL(doc.url)}" target="_blank" rel="noopener"><span class="pdf-icon">PDF</span><div><strong>${e(doc.title)} ↗</strong><small>Страницы ${e(doc.pages)} · ${e(sources.get(doc.source_id).author||'Документация')}</small><small>${e(doc.scope)}</small></div></a>`).join('')}${!d.gallery.length&&!d.diagrams.length&&!d.documents?.length?'<div class="callout"><strong>Схема платы пока не найдена</strong><p>Доступны документы о чипах и драйвере. Номер ревизии и фотографию конкретной PCB ещё нужно добавить.</p></div>':''}`;
 main.innerHTML=`<div class="wrap"><header class="page-head"><div class="breadcrumb"><a href="#devices">Техника под разбор</a><span>/</span><span>${e(d.title)}</span></div><span class="eyebrow">${e(categoryNames[d.category])} / карточка устройства</span><h1>${e(d.title)}</h1><p class="lead">${e(d.summary)}</p><div class="status-line"><span class="badge">Есть источники</span><span>Аппаратные испытания ARC не проведены</span></div></header><div class="detail-layout">${outline(items)}<div>${section('identity','01','Что за устройство',`<div class="two-col"><dl class="identity">${d.identity.map(([k,v])=>`<div><dt>${e(k)}</dt><dd>${e(v)}</dd></div>`).join('')}</dl>${architecture|| (d.image?figure(d.image):`<div class="arch">${technicalGraphic(d.category)}<p>Функциональная иллюстрация ARC по документации. Не принципиальная схема.</p></div>`)}</div>`)}${section('chips','02','Плата и компоненты',chips)}${section('diagrams','03','Фотографии и схемы',diagrams)}${section('reuse','04','Что можно использовать',`${bullets(d.reuse)}<h3>Где искать донора</h3><p>${e(d.where)}</p><div class="callout warning"><strong>Перед подключением</strong>${bullets(d.limits)}</div>${d.routes.length?`<h3>Из этого можно собрать</h3>${d.routes.map(id=>{const r=data.routes.find(r=>r.id===id);return `<a class="document-link" href="#build/${id}"><span class="arrow">↗</span><div><strong>${e(r.title)}</strong><small>${e(r.result)}</small></div></a>`;}).join('')}`:'<div class="callout"><strong>Готовая сборка из этой платы ещё не подтверждена</strong><p>Состав известен частично. Для рецепта нужны схема отдельного узла, питание, управление и проверка на стенде.</p></div>'}${(d.related||[]).map(id=>`<a class="btn" href="#device/${id}">Связанный разбор: ${e(data.devices.find(d=>d.id===id).title)} ↗</a>`).join('')}`)}${section('evidence','05','На чём основаны выводы',d.claims.map(c=>`<div class="claim"><p>${e(c.text)}</p><small>${e(c.scope)}${c.locator?' · '+e(c.locator):''}</small>${links(c.source_ids)}</div>`).join(''))}${section('sources','06','Первоисточники',`<div class="source-list">${sourceRows(d.source_ids)}</div>`)}</div></div></div>`;
}
function wiringGraphic() { return `<div class="wiring-preview"><svg viewBox="0 0 760 330" role="img" aria-label="Подключение UART: TX к U0R, RX к U0T, общая земля; отдельные 5 V на питание ESP32-CAM"><g fill="#f2f4ec" stroke="#adb79f"><rect x="30" y="40" width="195" height="170" rx="5"/><rect x="500" y="35" width="230" height="270" rx="5"/><rect x="30" y="240" width="195" height="65" rx="5"/></g><g font-family="Arial,sans-serif" fill="#2f3b29" font-size="17"><text x="50" y="70">USB–UART</text><text x="50" y="91" font-size="12">логика 3,3 V</text><text x="520" y="70">ESP32-CAM</text><text x="50" y="265">Источник 5 V</text></g><g fill="none" stroke-width="2.5"><path d="M225 120h275M225 157h275" stroke="#758d5d"/><path d="M225 192h90v30h185m-185 0v64h-90" stroke="#8d9187"/><path d="M225 269h170v-93h105" stroke="#b86b3d"/><path d="M730 247h12v39h-12" stroke="#9b8566" stroke-dasharray="5 4"/></g><g font-family="monospace" fill="#46543e" font-size="14"><text x="178" y="125">TX</text><text x="178" y="162">RX</text><text x="167" y="197">GND</text><text x="520" y="125">U0R / GPIO3</text><text x="520" y="162">U0T / GPIO1</text><text x="520" y="181">5V</text><text x="520" y="227">GND</text><text x="520" y="252">GPIO0</text><text x="520" y="291">GND</text></g><text x="277" y="315" font-family="Arial,sans-serif" font-size="12" fill="#75634d">GPIO0–GND: только загрузка. Убрать перед запуском.</text></svg><p>Схема подключения ARC по документации Espressif / Prusa. Подключай при снятом питании; 5 V не подаются на сигнальные выводы.</p></div>`; }
function buildPage(id) {
 const r=data.routes.find(r=>r.id===id);if(!r)return notFound();
 const d=data.devices.find(d=>d.id===r.device_id);const m=readiness(r,state.inventory);
 const items=[['result','Результат'],['bom','Что понадобится'],['wiring','Как подключить'],['firmware',r.firmware?'Прошивка':'Команды'],['steps','Порядок запуска'],['tests','Проверка'],['sources','Источники']];
 const firmware=r.firmware?`<p>${e(r.firmware.title)}</p><div class="callout"><p>${e(r.firmware.config)}</p></div><div class="hero-actions"><a class="btn primary" href="${e(r.firmware.download)}" download>Скачать подготовленный пример ↓</a><a class="btn" href="${safeURL(sources.get(r.firmware.source).url)}" target="_blank" rel="noopener">Официальный исходник ↗</a></div><p class="caption-label">Зафиксированная версия 3.3.12. Сборка прошивки и запуск на плате здесь не выполнялись.</p>`:`<p>Команды выполняются на твоём устройстве. Подставь найденный видеоузел вместо videoX.</p><pre class="code-block">${e(r.commands)}</pre>`;
 main.innerHTML=`<div class="wrap"><header class="page-head"><div class="breadcrumb"><a href="#explore">Сборки</a><span>/</span><span>${e(r.title)}</span></div><span class="eyebrow">От деталей до первого запуска</span><h1>${e(r.title)}</h1><p class="lead">${e(r.result)}</p><div class="status-line"><span class="badge">По документации</span><span>${e(r.time)}</span><span>На стенде не испытано</span></div></header><div class="detail-layout">${outline(items,`<button class="btn" data-download="${r.id}">Скачать план ↓</button>`)}<div>${section('result','01','Что получится',`<div class="callout"><strong>${e(r.subtitle)}</strong><p>${e(r.result)}</p></div><a class="small-link" href="#device/${d.id}">Посмотреть плату и чипы: ${e(d.title)} ↗</a>${bullets(r.limits)}`)}${section('bom','02','Что понадобится',`<p>Отметь имеющиеся позиции после проверки. Список хранится в этом браузере.</p><div class="bom-list">${m.rows.map(req=>`<div class="bom-row"><input type="checkbox" id="bom-${req.id}" data-bom="${req.id}" data-route="${r.id}" ${!req.missing?'checked':''}><label for="bom-${req.id}">${e(req.name)}<span><b>Где взять:</b> ${e(req.where)}</span><span><b>Проверить:</b> ${e(req.check)}</span></label><span class="bom-count">× ${req.qty}</span></div>`).join('')}</div><div id="readiness" class="readiness"></div><button class="btn" data-shopping="${r.id}">Скачать недостающий комплект ↓</button>`)}${section('wiring','03','Как подключить',`${r.id==='wifi-camera'?wiringGraphic():''}<div class="table-wrap"><table><thead><tr><th>Откуда</th><th>Куда</th><th>Условие</th></tr></thead><tbody>${r.wiring.map(row=>`<tr>${row.map(c=>`<td>${e(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="caption-label">Подробная документация</p>${r.diagrams.map(id=>figure(id,true)).join('')}`)}${section('firmware','04',r.firmware?'Прошивка':'Команды',firmware)}${section('steps','05','Порядок запуска',r.steps.map(([title,action,pass],i)=>`<div class="instruction"><span class="step-number">${i+1}</span><div><h3>${e(title)}</h3><p>${e(action)}</p><div class="pass">Успех: ${e(pass)}</div></div></div>`).join(''))}${section('tests','06','Проверь результат',`<p>Эти отметки — твой журнал проверки. Они не меняют общий статус маршрута.</p>${r.tests.map((t,i)=>`<label class="test-item"><input type="checkbox" data-test="${r.id}:${i}" ${state.tests[r.id+':'+i]?'checked':''}>${e(t)}</label>`).join('')}<div class="test-result" id="test-result"></div><h3 style="margin-top:28px">Если не заработало</h3>${r.troubleshoot.map(([a,b])=>`<details class="trouble"><summary>${e(a)}</summary><p>${e(b)}</p></details>`).join('')}<div class="hero-actions" style="margin-top:25px"><button class="btn primary" data-download="${r.id}">Скачать весь маршрут ↓</button><button class="btn" data-print>Распечатать</button></div>`)}${section('sources','07','Источники маршрута',`<div class="source-list">${sourceRows(r.source_ids)}</div>`)}</div></div></div>`;
 updateReadiness(r);updateTests(r);
}
function updateReadiness(r) { const m=readiness(r,state.inventory);$('#readiness').innerHTML=`<strong>${m.have} из ${m.total} позиций отмечены${m.complete?' · комплект собран':''}</strong><div class="meter"><span style="width:${Math.round(m.have/m.total*100)}%"></span></div>`; }
function updateTests(r) { const n=r.tests.filter((_,i)=>state.tests[r.id+':'+i]===true).length;$('#test-result').textContent=`В твоём журнале: ${n} из ${r.tests.length}. ${n===r.tests.length?'Все пункты отмечены тобой. Общий статус остаётся «на стенде ARC не испытано».':''}`; }
function learnPage() {
 const steps=[
 ['Начни с полезного результата.','Определи, что должно происходить: увидеть картинку, записать движение, узнать об открытой двери или подать воду. У каждой задачи будут свой состав и проверка.','«Камера показывает живое изображение на телефоне в одной Wi-Fi-сети» — проверяемый результат. «Система безопасности» пока слишком широко.','#explore','Выбрать маршрут'],
 ['Узнай устройство и плату.','Ищи по модели, PNC, маркировке PCB и номеру ревизии. На форумах полезны сообщения самого владельца с фотографиями обеих сторон платы и итогом ремонта. Сохраняй точную ссылку на сообщение.','У Electrolux EWF12844 есть основная плата EWX14, отдельный инвертор и панель. У каждого узла свой номер детали.','#device/ewf12844','Посмотреть конкретный разбор'],
 ['Проверь чип и его роль.','Сопоставь читаемую маркировку с даташитом производителя. Отдельно запиши питание, сигнальные уровни, интерфейс, прошивку и необходимые соседние компоненты.','LNK304 — контроллер источника питания. Он не выполняет роль основного процессора. Реле с катушкой 12 V не подключается прямо к GPIO.','#device/aeg-t55640','Открыть пример из форума'],
 ['Сохрани работающий узел.','Часто разумнее взять целый модуль с кабелем и объективом. Отдельный выпаянный сенсор потребует нового питания, тактирования, контроллера и драйвера.','Sony Eye уже содержит сенсор OV772x и USB-мост OV534. Для Linux нужен gspca_ov534; это не универсальная UVC-камера.','#device/ps3-eye','Разобраться с совместимостью'],
 ['Собери недостающий комплект.','В маршруте должны быть все позиции: питание, переходники, инструмент, хост, программное обеспечение, корпус. Для каждой позиции нужны условия совместимости и место поиска.','У ESP32-CAM питание платы 5 V, а сигналы UART — 3,3 V. Одинаковый разъём не гарантирует правильное напряжение.','#build/wifi-camera','Открыть комплект и схему'],
 ['Пройди проверку до конца.','Сначала добейся первого кадра или реакции датчика. Затем проверь повторный запуск и длительную работу. Запиши точную ревизию, версию прошивки, результат и обнаруженные ограничения.','В ARC сейчас три маршрута по документации. Отметки в твоём журнале не превращают их в независимо испытанные устройства.','#notebook','Записать свой результат']
 ];
 main.innerHTML=`<div class="wrap"><header class="page-head learn-intro"><span class="eyebrow">Руководство / с первого шага</span><h1>Из найденной платы —<br>в полезную вещь.</h1><p class="lead">Не нужно заранее знать все чипы. Нужен понятный порядок: найти доказательство, проверить совместимость, собрать и измерить результат.</p></header><div class="learn-steps">${steps.map(([title,body,example,link,label],i)=>`<section class="learn-step"><span class="step-number">${i+1}</span><div><h2>${title}</h2><p>${body}</p><div class="example">${example}</div><a class="small-link" href="${link}">${label} ↗</a></div></section>`).join('')}<div class="callout"><strong>Как ARC читает форумы</strong><p>Модель → конкретная плата → наблюдение автора → ссылка и дата → проверка. Догадки, фотографии и итог ремонта хранятся отдельно. Одинаковое название модели не объединяет автоматически две ревизии платы.</p></div><a href="#sources" class="btn">Посмотреть источники ↗</a></div></div>`;
}
function sourcesPage() {
 state.query='';main.innerHTML=`<div class="wrap"><header class="page-head"><span class="eyebrow">Первоисточники / 23.10.2026</span><h1>Не «где-то написано».<br>Вот откуда мы знаем.</h1><p class="lead">Оригинальные разборы, сообщения владельцев, сервисные документы и даташиты. В каждой карточке указано, какой вывод относится к какому источнику.</p></header><label class="search"><span aria-hidden="true">⌕</span><input id="source-search" type="search" placeholder="Форум, чип, производитель…" aria-label="Поиск по источникам"></label><div id="source-grid" class="source-grid"></div><div class="callout"><strong>Исходный корпус — отдельно</strong><p>В старом наборе ARC есть 1 225 извлечённых проектов и 1 115 записей устройств. Они требуют проверки источников и технических связей. Этот объём не считается числом готовых инструкций.</p><a class="small-link" href="archive.html">Искать в исходном корпусе ↗</a></div></div>`;renderSources();
}
function renderSources() { const list=data.sources.filter(s=>matches(s,state.query));$('#source-grid').innerHTML=list.length?sourceRows(list.map(s=>s.id)):'<div class="empty">Источников по этому запросу пока нет.</div>'; }
function notebookPage() {
 main.innerHTML=`<div class="wrap"><header class="page-head"><span class="eyebrow">Личный журнал</span><h1>Сохрани то,<br>что удалось узнать.</h1><p class="lead">Модель, плата, ссылка на разбор и результат проверки. Записи остаются в этом браузере; можно выгрузить их в JSON.</p></header><div class="notebook-layout"><form class="form-panel" id="note-form"><h3>Новая запись</h3><label>Устройство / модель<input name="model" required maxlength="160" placeholder="Например, AEG T55640"></label><label>Маркировка платы / ревизия<input name="board" maxlength="160" placeholder="Запиши ровно то, что видно"></label><label>Ссылка на первоисточник<input name="url" type="url" placeholder="https://…"></label><label>Наблюдение и что ещё нужно проверить<textarea name="note" maxlength="2500" placeholder="Кто сообщил? Есть ли фото? Какая версия прошивки? Что получилось при проверке?"></textarea></label><button class="btn primary" type="submit">Сохранить запись +</button><p class="caption-label">Это заметка, а не автоматическая проверка схемы или совместимости.</p></form><div><div class="section-heading"><h3>Твои записи</h3><button class="small-link" data-export>Экспорт JSON ↓</button></div><div id="notes-list"></div><label class="btn">Импорт JSON <input type="file" id="notebook-import" accept="application/json,.json" style="max-width:200px;font-size:11px"></label></div></div></div>`;renderNotes();
}
function renderNotes() { $('#notes-list').innerHTML=state.cases.length?state.cases.map((c,i)=>`<article class="note-card"><span class="badge">Личная запись</span><h3 style="margin-top:12px">${e(c.model)}</h3>${c.board?`<p>Плата: ${e(c.board)}</p>`:''}<p>${e(c.note)}</p><div class="note-actions">${c.url?`<a href="${safeURL(c.url)}" target="_blank" rel="noopener">Первоначальный источник ↗</a>`:'<span>Источник не указан</span>'}<button data-delete-note="${i}">Удалить</button></div></article>`).join(''):'<div class="empty"><h3>Пока нет записей</h3><p>Сюда можно добавить разбор с форума или свой результат проверки.</p></div>'; }
function notFound() { main.innerHTML='<div class="wrap"><header class="page-head"><h1>Карточка не найдена.</h1><p>Возможно, ссылка относится к старой версии.</p><a class="btn" href="#explore">Вернуться к сборкам</a></header></div>'; }
function route() {
 if(!data)return;
 const hash=location.hash.slice(1)||'explore';if(hash==='content'){main.focus();return;}
 const [page,id]=hash.split('/');
 const active=page==='device'?'devices':page==='build'?'explore':page;
 document.querySelectorAll('[data-nav]').forEach(a=>{if(a.dataset.nav===active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 if(page==='explore'||page==='devices')catalogPage(page==='devices'?'devices':'routes');
 else if(page==='device')devicePage(id);else if(page==='build')buildPage(id);else if(page==='learn')learnPage();else if(page==='sources')sourcesPage();else if(page==='notebook')notebookPage();else notFound();
 document.title=`${main.querySelector('h1')?.textContent||'Справочник'} — ARC`;
 window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true});
}
const viewer=$('#image-viewer');
viewer.querySelector('button').addEventListener('click',()=>viewer.close());
viewer.addEventListener('click',ev=>{if(ev.target===viewer){const r=viewer.getBoundingClientRect();if(ev.clientX<r.left||ev.clientX>r.right||ev.clientY<r.top||ev.clientY>r.bottom)viewer.close();}});
document.addEventListener('error',ev=>{const img=ev.target;if(img instanceof HTMLImageElement){img.hidden=true;const message=document.createElement('span');message.className='image-unavailable';message.textContent='Изображение не загрузилось. Оригинал доступен по ссылке в разборе.';img.after(message);}},true);
document.addEventListener('input',ev=>{if(ev.target.id==='catalog-search'){state.query=ev.target.value;renderCards();}if(ev.target.id==='source-search'){state.query=ev.target.value;renderSources();}});
document.addEventListener('click',ev=>{
 const button=ev.target.closest('button');if(!button)return;const d=button.dataset;
 if(d.jump)document.getElementById(d.jump)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});
 if(d.category){state.category=d.category;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.category===d.category)));renderCards();}
 if(d.image){const a=assets.get(d.image);$('#image-content').innerHTML=`<img src="${e(a.src)}" alt="${e(captions[d.image]||a.id)}" referrerpolicy="no-referrer"><p>${e(captions[d.image]||a.caption||a.id)}<br>${e(a.credit)} · <a href="${safeURL(a.url)}" target="_blank" rel="noopener">Открыть оригинал ↗</a></p>`;viewer.showModal();}
 if(d.download){const r=data.routes.find(r=>r.id===d.download);download(`ARC-${r.id}.txt`,planText(r,state.inventory,data.sources));}
 if(d.shopping){const r=data.routes.find(r=>r.id===d.shopping);const rows=readiness(r,state.inventory).rows.filter(r=>r.missing);download(`ARC-${r.id}-missing.txt`,`ARC — ${r.title}\nНедостающий комплект\n\n${rows.length?rows.map(r=>`${r.name} × ${r.missing}\nГде взять: ${r.where}\nПроверить: ${r.check}`).join('\n\n'):'Все позиции отмечены. Следующий шаг — проверка совместимости и запуск.'}\n`);}
 if(d.print!==undefined)window.print();
 if(d.export!==undefined)download('ARC-notebook.json',JSON.stringify({version:2,cases:state.cases,inventory:state.inventory,tests:state.tests},null,2),'application/json');
 if(d.deleteNote!==undefined){state.cases.splice(Number(d.deleteNote),1);save();renderNotes();notify('Запись удалена.');}
});
document.addEventListener('change',async ev=>{
 const input=ev.target;
 if(input.dataset.bom){const r=data.routes.find(r=>r.id===input.dataset.route);const req=r.requirements.find(q=>q.id===input.dataset.bom);state.inventory[req.id]=input.checked?req.qty:0;save();updateReadiness(r);}
 if(input.dataset.test){state.tests[input.dataset.test]=input.checked;save();const r=data.routes.find(r=>input.dataset.test.startsWith(r.id+':'));updateTests(r);}
 if(input.id==='notebook-import'&&input.files[0]){
  try{const file=input.files[0];if(file.size>1_000_000)throw Error('Файл слишком большой (до 1 МБ).');const obj=JSON.parse(await file.text());if(obj.version!==2||!Array.isArray(obj.cases))throw Error('Нужен экспорт ARC версии 2.');const cases=normalizeCases(obj.cases);if(cases.length!==obj.cases.length)throw Error('В файле есть неподдерживаемые записи.');state.cases=[...state.cases,...cases].slice(0,100);for(const r of data.routes){for(const req of r.requirements){if(obj.inventory?.[req.id]===req.qty)state.inventory[req.id]=req.qty;}r.tests.forEach((_,i)=>{const id=r.id+':'+i;if(obj.tests?.[id]===true)state.tests[id]=true;});}save();renderNotes();notify('Записи и отметки добавлены.');}catch(error){notify(error.message||'Не удалось прочитать файл.');}input.value='';
 }
});
document.addEventListener('submit',ev=>{
 if(ev.target.id!=='note-form')return;ev.preventDefault();const form=ev.target;const values=Object.fromEntries(new FormData(form));
 if(values.url&&safeURL(values.url)==='#')return notify('Для источника нужна ссылка HTTPS.');
 const cases=normalizeCases([values]);if(!cases.length)return notify('Укажи модель устройства.');if(state.cases.length>=100)return notify('Сначала экспортируй записи: журнал вмещает 100 заметок.');
 state.cases.unshift(cases[0]);save();form.reset();renderNotes();notify('Запись добавлена в журнал.');
});
window.addEventListener('hashchange',route);
let serviceReady=null;
if('serviceWorker' in navigator)serviceReady=navigator.serviceWorker.register('sw.js').then(()=>navigator.serviceWorker.ready).catch(()=>null);
$('#offline-save').addEventListener('click',async()=>{
 const b=$('#offline-save');b.disabled=true;b.textContent='Сохраняем…';
 try{if(!data||!serviceReady||!await serviceReady)throw Error('Офлайн-сохранение недоступно в этом браузере.');const cache=await caches.open('arc-field-v2');const local=data.assets.filter(a=>!a.src.startsWith('https://')).map(a=>a.src);await cache.addAll(['./','index.html','field.css','field.js','evidence-logic.js','data/evidence.json','assets/mono.woff2','assets/display.woff2','assets/favicon.svg',...local,'assets/firmware/esp32-camera-3.3.12.zip']);$('#offline-note').textContent='Сохранены новые разборы, планы, локальные схемы и прошивка. Фото с сайтов авторов, PDF и исходный корпус требуют сети или отдельного сохранения в архиве.';b.textContent='Сохранено ✓';notify('Новый справочник сохранён для офлайна.');}catch(error){b.textContent='Повторить сохранение ↓';notify(error.message);}finally{b.disabled=false;}
});
try { const response=await fetch('data/evidence.json');if(!response.ok)throw Error('HTTP '+response.status);data=await response.json();sources=new Map(data.sources.map(s=>[s.id,s]));assets=new Map(data.assets.map(s=>[s.id,s]));route(); }
catch { main.innerHTML='<div class="wrap"><header class="page-head"><h1>Не удалось загрузить справочник.</h1><p>Проверь соединение и обнови страницу.</p><a class="btn" href="index.html">Попробовать снова</a></header></div>'; }
